import { FormEvent, useEffect, useMemo, useState } from "react";
import {
  ArrowLeft, ArrowRight, Bell, Bot, BriefcaseBusiness, Building2, Check, ChevronDown,
  ChevronRight, CircleHelp, Compass, Eye, FilePlus2, FileText, Filter, Heart, Home as HomeIcon,
  Lightbulb, Lock, LogOut, Mail, Menu, MessageCircle, MoreHorizontal, Plus, Rocket,
  Search, Send, Settings as SettingsIcon, Shield, Sparkles, Star, Target, TrendingUp, UserRound, Users,
  X, Zap,
} from "lucide-react";

type Screen = "login" | "signup" | "recovery" | "reset" | "verify" | "onboarding" | "dashboard" | "for-you" | "explore" | "matches" | "my-opportunities" | "assistant" | "startup" | "settings" | "notifications" | "account" | "privacy" | "preferences" | "opportunity" | "match" | "create-company" | "create-opportunity" | "interest-success" | "opportunity-success";
type OpportunityType = "Todos" | "Editais" | "Eventos" | "POCs" | "Compras";

const opportunities = [
  { id: "edital", type: "Edital", title: "Edital Inovação Aberta 2026", short: "Apoio financeiro para startups com soluções B2B.", description: "Programa de inovação aberta para startups com soluções em dados e automação por IA. A oportunidade busca aplicações com potencial de validação em ambiente real.", match: 96, meta: "Prazo 15/10/2026 · Brasil · Remoto", tags: "setor • tecnologia • objetivo", color: "bg-[#fff2b8] text-[#795900]" },
  { id: "poc", type: "POC", title: "POC — Inteligência Operacional", short: "Empresa procura solução de IA para operação.", description: "Empresa Alpha busca startup para automatizar processos internos e testar inteligência operacional em um ambiente real.", match: 94, meta: "Resposta até sexta · Brasil · Híbrido", tags: "setor • tecnologia • objetivo", color: "bg-[#d9f1e5] text-[#16734d]" },
  { id: "evento", type: "Evento", title: "Startup Connect Recife", short: "Networking com empresas e ecossistema local.", description: "Evento para conectar startups, corporações e investidores em uma agenda de networking e negócios.", match: 89, meta: "22/10/2026 · Recife · Presencial", tags: "localização • objetivo", color: "bg-[#dff1f5] text-[#1e7080]" },
  { id: "compra", type: "Compra", title: "Compra — Dados & Analytics", short: "Demanda por plataforma de análise.", description: "Demanda empresarial por plataforma de análise de dados para apoiar decisões operacionais.", match: 87, meta: "Aberta · Brasil · Remoto", tags: "tecnologia • solução", color: "bg-[#ffe1c3] text-[#975524]" },
];

const nav = [
  { id: "dashboard", label: "Dashboard", icon: HomeIcon },
  { id: "for-you", label: "Para você", icon: Sparkles },
  { id: "explore", label: "Explorar", icon: Compass },
  { id: "matches", label: "Matches", icon: Heart },
  { id: "my-opportunities", label: "Minhas oportunidades", icon: FileText },
  { id: "assistant", label: "Assistente IA", icon: Bot },
];

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-start gap-2"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#ffd43b] text-[#052e5f]"><Rocket size={18} fill="currentColor" /></div><div><div className="text-[19px] font-extrabold tracking-[-.06em] text-[#062f61]">STARTIN</div>{!compact && <div className="mt-0.5 max-w-[135px] text-[10px] leading-3 text-[#68717d]">Oportunidades que combinam com sua startup.</div>}</div></div>;
}

function Field({ label, placeholder, type = "text", value, onChange }: { label: string; placeholder?: string; type?: string; value?: string; onChange?: (value: string) => void }) {
  return <label className="block"><span className="mb-2 block text-xs font-semibold text-[#203754]">{label}</span><input type={type} value={value} onChange={(e) => onChange?.(e.target.value)} placeholder={placeholder} className="h-11 w-full rounded-lg border border-[#dfe4e9] bg-white px-3 text-sm text-[#12355d] outline-none transition placeholder:text-[#9ba4ad] focus:border-[#075394] focus:ring-3 focus:ring-[#075394]/10" /></label>;
}

function PrimaryButton({ children, onClick, type = "button", full = false, secondary = false }: { children: React.ReactNode; onClick?: () => void; type?: "button" | "submit"; full?: boolean; secondary?: boolean }) {
  return <button type={type} onClick={onClick} className={`${full ? "w-full" : ""} inline-flex h-11 items-center justify-center gap-2 rounded-lg px-5 text-sm font-bold transition active:scale-[.98] ${secondary ? "border border-[#cfd7e0] bg-white text-[#063464] hover:border-[#075394]" : "bg-[#075394] text-white shadow-[0_8px_16px_rgba(7,83,148,.16)] hover:bg-[#064577]"}`}>{children}</button>;
}

function OrbitMark() {
  return <div className="relative flex h-24 w-24 items-center justify-center"><div className="absolute inset-1 rounded-full border border-[#ffd43b]/70 rotate-[-24deg]" /><div className="absolute inset-4 rounded-full border border-[#ffd43b]/40 rotate-[30deg]" /><div className="relative flex h-11 w-11 items-center justify-center rounded-2xl bg-[#ffd43b] text-[#062f61] rotate-[-18deg]"><Rocket size={22} fill="currentColor" /></div></div>;
}

function AuthShell({ children, sideTitle, sideText }: { children: React.ReactNode; sideTitle: React.ReactNode; sideText: string }) {
  return <div className="min-h-screen bg-[#f3f5f8] lg:grid lg:grid-cols-[43%_57%]"><section className="relative hidden overflow-hidden bg-[#062f61] px-12 py-10 text-white lg:flex lg:flex-col lg:justify-between"><div className="relative z-10"><div className="flex items-center gap-3 text-[22px] font-extrabold tracking-[.02em]">Start<span className="text-[#ffd43b]">In</span></div><div className="mt-28 max-w-[405px]"><OrbitMark /><h1 className="mt-8 text-[45px] font-extrabold leading-[1.02] tracking-[-.065em]">{sideTitle}</h1><p className="mt-7 max-w-[350px] text-[15px] leading-6 text-[#c7d8ea]">{sideText}</p></div></div><div className="relative z-10 text-xs text-[#a8c0d9]">StartIn © 2026 · O ecossistema para os próximos grandes começos.</div><div className="absolute -bottom-44 -right-28 h-[470px] w-[470px] rounded-full border-[54px] border-[#174b7e]" /><div className="absolute -right-10 top-24 h-64 w-64 rounded-full border border-[#2a6598]/40" /></section><section className="flex min-h-screen items-center justify-center p-5 md:p-10"><div className="w-full max-w-[520px] rounded-[28px] border border-[#e4e8ec] bg-white p-7 shadow-[0_20px_60px_rgba(6,47,97,.06)] md:p-10"><div className="mb-8 lg:hidden"><Logo /></div>{children}</div></section></div>;
}

function Login({ go }: { go: (screen: Screen) => void }) {
  const [email, setEmail] = useState(""); const [password, setPassword] = useState("");
  return <AuthShell sideTitle={<>Conecte sua startup a oportunidades <span className="text-[#ffd43b]">certas.</span></>} sideText="Editais, eventos e clientes em um só lugar, personalizados com IA para o seu negócio."><div><p className="text-sm font-semibold text-[#6c7782]">Bem-vinda à StartIn</p><h2 className="mt-2 text-[28px] font-extrabold tracking-[-.05em] text-[#062f61]">Entre na sua conta</h2><p className="mt-2 text-sm text-[#77818c]">Acesse suas oportunidades personalizadas.</p><form onSubmit={(e) => { e.preventDefault(); localStorage.setItem("startin-auth", "1"); go("dashboard"); }} className="mt-8 space-y-5"><Field label="E-mail" placeholder="seu@email.com" value={email} onChange={setEmail} /><Field label="Senha" placeholder="********" type="password" value={password} onChange={setPassword} /><button type="button" onClick={() => go("recovery")} className="-mt-2 text-left text-xs font-semibold text-[#075394] hover:underline">Esqueceu sua senha?</button><PrimaryButton type="submit" full>Entrar <ArrowRight size={16} /></PrimaryButton></form><div className="my-7 flex items-center gap-3 text-[11px] text-[#a0a7ae]"><div className="h-px flex-1 bg-[#e2e6eb]" />ou<div className="h-px flex-1 bg-[#e2e6eb]" /></div><PrimaryButton secondary full onClick={() => go("signup")}>Crie sua conta</PrimaryButton></div></AuthShell>;
}

function Signup({ go }: { go: (screen: Screen) => void }) {
  const [form, setForm] = useState({ cnpj: "", email: "", password: "", confirm: "" }); const set = (key: keyof typeof form) => (value: string) => setForm((f) => ({ ...f, [key]: value }));
  return <AuthShell sideTitle={<>Crie sua conta e comece a encontrar <span className="text-[#ffd43b]">oportunidades.</span></>} sideText="Cadastre-se para conectar sua startup a editais, eventos, POCs e clientes personalizados com IA."><div><button onClick={() => go("login")} className="mb-7 flex items-center gap-2 text-xs font-bold text-[#71808e]"><ArrowLeft size={14} /> Voltar para login</button><h2 className="text-[28px] font-extrabold tracking-[-.05em] text-[#062f61]">Crie sua conta</h2><p className="mt-2 text-sm text-[#77818c]">Preencha seus dados para começar.</p><form onSubmit={(e) => { e.preventDefault(); go("verify"); }} className="mt-7 space-y-4"><Field label="CNPJ" placeholder="AA.AAA.AAA/AAAA-DV" value={form.cnpj} onChange={set("cnpj")} /><Field label="E-mail" placeholder="seu@email.com" value={form.email} onChange={set("email")} /><Field label="Senha" placeholder="Crie uma senha" type="password" value={form.password} onChange={set("password")} /><Field label="Confirmar senha" placeholder="Repita sua senha" type="password" value={form.confirm} onChange={set("confirm")} /><p className="text-[11px] leading-4 text-[#88929d]">Ao criar sua conta, você concorda com os <span className="font-semibold text-[#075394]">Termos de Uso</span> e a <span className="font-semibold text-[#075394]">Política de Privacidade</span>.</p><PrimaryButton type="submit" full>Criar conta <ArrowRight size={16} /></PrimaryButton></form><p className="mt-6 text-center text-xs text-[#79848f]">Já possui uma conta? <button onClick={() => go("login")} className="font-bold text-[#075394]">Entrar</button></p></div></AuthShell>;
}

function Recovery({ go }: { go: (screen: Screen) => void }) { const [email, setEmail] = useState(""); return <AuthShell sideTitle={<>Não se preocupe, vamos ajudar <span className="text-[#ffd43b]">você.</span></>} sideText="Informe o e-mail cadastrado e enviaremos as instruções para redefinir sua senha."><button onClick={() => go("login")} className="mb-8 flex items-center gap-2 text-xs font-bold text-[#71808e]"><ArrowLeft size={14} /> Voltar para login</button><div className="mb-5 flex h-12 w-12 items-center justify-center rounded-2xl bg-[#fff2bf] text-[#755a00]"><Mail size={21} /></div><h2 className="text-[28px] font-extrabold tracking-[-.05em] text-[#062f61]">Esqueceu sua senha?</h2><p className="mt-2 text-sm leading-5 text-[#77818c]">Digite seu e-mail para receber um link de recuperação.</p><form onSubmit={(e) => { e.preventDefault(); go("reset"); }} className="mt-8 space-y-5"><Field label="E-mail" placeholder="seu@email.com" value={email} onChange={setEmail} /><PrimaryButton type="submit" full>Enviar link de recuperação <ArrowRight size={16} /></PrimaryButton></form></AuthShell>; }

function TextAreaField({ label, placeholder }: { label: string; placeholder: string }) {
  return <label className="block"><span className="mb-2 block text-xs font-semibold text-[#203754]">{label}</span><textarea placeholder={placeholder} className="min-h-[92px] w-full resize-none rounded-lg border border-[#dfe4e9] bg-white p-3 text-sm text-[#12355d] outline-none transition placeholder:text-[#9ba4ad] focus:border-[#075394] focus:ring-3 focus:ring-[#075394]/10" /></label>;
}

function Onboarding({ go }: { go: (s: Screen) => void }) {
  const [step, setStep] = useState(0);
  const [name, setName] = useState("Nexa Health");
  const labels = ["Identidade", "Solução", "Mercado", "Momento", "Objetivos", "Matching"];
  if (step === 5) return <div className="min-h-screen bg-[#f7f9fb] p-6 md:p-10"><div className="mx-auto max-w-[1180px]"><Logo /><div className="mx-auto mt-20 max-w-[650px] text-center"><div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-[#d9f1e5] text-[#18734d]"><Check size={30} strokeWidth={3} /></div><h1 className="mt-7 text-[34px] font-extrabold tracking-[-.05em] text-[#062f61]">Sua startup está pronta!</h1><p className="mt-3 text-sm text-[#6d7781]">Seu perfil foi configurado e a StartIn já pode começar a encontrar oportunidades.</p><div className="mt-12 grid grid-cols-2 gap-3 md:grid-cols-4">{["Identidade", "Solução", "Mercado", "Objetivos"].map((x, i) => <div key={x} className="rounded-xl border border-[#dfe5ea] bg-white p-4 text-left"><div className="text-xs font-bold text-[#075394]">0{i + 1}</div><div className="mt-3 text-xs font-semibold text-[#263f5d]">{x}</div><div className="mt-1 flex items-center gap-1 text-[10px] text-[#29815d]"><Check size={11} /> Concluído</div></div>)}</div><div className="mt-10"><PrimaryButton onClick={() => { localStorage.setItem("startin-auth", "1"); go("dashboard"); }}>Ir para o Dashboard <ArrowRight size={16} /></PrimaryButton></div></div></div></div>;

  const common = <div className="grid gap-5 md:grid-cols-2"><Field label="Nome da startup" value={name} onChange={setName} /><Field label="Área principal" placeholder="Healthtech" /><div className="md:col-span-2"><TextAreaField label="Descrição curta da startup" placeholder="Plataforma de IA para apoiar a gestão e análise de dados em saúde." /></div><Field label="Localização" placeholder="Recife, PE" /><Field label="CNPJ" placeholder="AA.AAA.AAA/AAAA-DV" /><Field label="Site" placeholder="https://" /><Field label="Ano de fundação" placeholder="2024" /></div>;
  const solution = <div className="grid gap-5 md:grid-cols-2"><TextAreaField label="Problema que resolve" placeholder="Gestão ineficiente e decisões baseadas em dados fragmentados." /><TextAreaField label="Como a solução funciona" placeholder="Explique o produto, o fluxo e a tecnologia utilizada." /><TextAreaField label="O que torna sua solução diferente?" placeholder="Diferenciais competitivos e ganhos para o cliente." /><TextAreaField label="Impacto gerado" placeholder="Resultados que a solução pode gerar." /><Field label="Tecnologias principais" placeholder="IA, dados, automação" /><Field label="Modelo de negócio" placeholder="SaaS B2B" /></div>;
  const market = <div className="grid gap-5 md:grid-cols-2"><Field label="Público-alvo" placeholder="Empresas de saúde e operações B2B" /><Field label="Setor principal" placeholder="Saúde" /><Field label="Região de atuação" placeholder="Brasil" /><Field label="Estado" placeholder="Pernambuco" /><Field label="Perfil de cliente" placeholder="Médias e grandes empresas" /><Field label="Tamanho do mercado" placeholder="R$ 2 bilhões" /><Field label="Concorrentes" placeholder="Liste seus principais concorrentes" /><Field label="Canal principal" placeholder="Vendas consultivas" /></div>;
  const moment = <div className="grid gap-5 md:grid-cols-2"><Field label="Estágio atual" placeholder="Tração" /><Field label="Tração / clientes" placeholder="12 clientes ativos" /><Field label="Maturidade do produto" placeholder="Produto validado" /><Field label="Tamanho do time" placeholder="8 pessoas" /><Field label="Receita anual" placeholder="R$ 240 mil" /><Field label="Crescimento recente" placeholder="+80% no último ano" /><Field label="Investimento captado" placeholder="R$ 500 mil" /></div>;
  const goals = <div className="grid gap-5 md:grid-cols-2"><Field label="Principal objetivo" placeholder="Expandir para novos mercados" /><Field label="Necessidade de investimento" placeholder="R$ 1 milhão" /><Field label="Prazo de execução" placeholder="12 meses" /><Field label="Uso dos recursos" placeholder="Produto, equipe e expansão comercial" /><Field label="Meta para os próximos 12 meses" placeholder="Dobrar a base de clientes" /><Field label="Prioridade estratégica" placeholder="Escala comercial" /><Field label="Parceiros desejados" placeholder="Fusões, canais e clientes" /></div>;
  const content = [common, solution, market, moment, goals][step];
  const subtitles = ["Essas informações alimentam o matching da StartIn.", "Conte como sua startup resolve um problema real e gera valor.", "Descreva o mercado em que sua startup atua.", "Entenda em que estágio sua startup está e quais resultados já alcançou.", "Defina o que sua startup busca e como pretende crescer nos próximos meses."];
  return <div className="min-h-screen bg-[#f7f9fb] px-5 py-7 md:px-10"><div className="mx-auto max-w-[1180px]"><Logo /><div className="mt-12 grid gap-10 lg:grid-cols-[225px_1fr]"><div><h1 className="text-[30px] font-extrabold leading-[1.05] tracking-[-.06em] text-[#062f61]">Oportunidades que combinam <span className="text-[#075394]">com sua startup.</span></h1><p className="mt-4 text-sm leading-5 text-[#78828d]">Vamos conhecer sua startup para encontrar os melhores matches.</p></div><div><p className="text-sm font-semibold text-[#6d7781]">Vamos conhecer sua startup</p><p className="mt-1 text-xs text-[#9aa2aa]">{subtitles[step]}</p><div className="mt-7 grid grid-cols-3 gap-2 md:grid-cols-6">{labels.map((x, i) => <div key={x} className={`border-t-2 pt-2 text-[10px] font-semibold ${i <= step ? "border-[#ffd43b] text-[#075394]" : "border-[#dce2e7] text-[#9ca5ad]"}`}>0{i + 1} {x}</div>)}</div><div className="mt-10 rounded-2xl border border-[#e0e5e9] bg-white p-6 md:p-8"><h2 className="text-[22px] font-extrabold tracking-[-.04em] text-[#062f61]">0{step + 1} — {labels[step]}</h2><p className="mt-2 text-sm text-[#77818c]">{subtitles[step]}</p><div className="mt-7">{content}</div><div className="mt-8 flex justify-end"><PrimaryButton onClick={() => setStep((s) => Math.min(5, s + 1))}>{step === 4 ? "Finalizar perfil" : "Continuar"} <ArrowRight size={16} /></PrimaryButton></div></div></div></div></div></div>;
}

function Sidebar({ screen, go, onClose }: { screen: Screen; go: (s: Screen) => void; onClose: () => void }) { return <aside className="fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col border-r border-[#e5e9ed] bg-white px-5 py-7 shadow-xl lg:shadow-none"><div className="flex items-start justify-between"><Logo /><button onClick={onClose} className="rounded-lg p-1 text-[#83909b] lg:hidden"><X size={18} /></button></div><nav className="mt-12 space-y-1">{nav.map((item) => { const Icon = item.icon; return <button key={item.id} onClick={() => { go(item.id as Screen); onClose(); }} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm font-semibold transition ${screen === item.id ? "bg-[#f1f4f7] text-[#062f61]" : "text-[#65717c] hover:bg-[#f8fafc] hover:text-[#062f61]"}`}><Icon size={17} strokeWidth={screen === item.id ? 2.5 : 1.8} />{item.label}{item.id === "matches" && <span className="ml-auto rounded-full bg-[#fff1b4] px-2 py-0.5 text-[10px] text-[#725800]">2</span>}</button>; })}</nav><div className="mt-auto"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.14em] text-[#a0a8af]">Conta</p><button onClick={() => go("startup")} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm font-semibold ${screen === "startup" ? "bg-[#f1f4f7] text-[#062f61]" : "text-[#65717c]"}`}><Building2 size={17} />Minha startup</button><button onClick={() => go("settings")} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm font-semibold ${screen === "settings" ? "bg-[#f1f4f7] text-[#062f61]" : "text-[#65717c]"}`}><SettingsIcon size={17} />Configurações</button><button onClick={() => { localStorage.removeItem("startin-auth"); go("login"); }} className="mt-3 flex w-full items-center gap-3 border-t border-[#edf0f2] px-3 pt-4 text-left text-xs font-semibold text-[#8a949d] hover:text-[#075394]"><LogOut size={16} />Sair</button></div></aside>; }

function AppShell({ screen, go, children }: { screen: Screen; go: (s: Screen) => void; children: React.ReactNode }) { const [menu, setMenu] = useState(false); return <div className="min-h-screen bg-[#f7f9fb] text-[#112d4f]"><div className={`${menu ? "block" : "hidden"} fixed inset-0 z-30 bg-[#062f61]/20 lg:hidden`} onClick={() => setMenu(false)} /><div className={`${menu ? "translate-x-0" : "-translate-x-full"} lg:translate-x-0`}><Sidebar screen={screen} go={go} onClose={() => setMenu(false)} /></div><div className="lg:pl-[248px]"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-[#e8edf0] bg-white/95 px-5 backdrop-blur md:px-9"><button onClick={() => setMenu(true)} className="rounded-lg p-2 text-[#687681] lg:hidden"><Menu size={20} /></button><div className="hidden text-xs text-[#8b959e] sm:block">StartIn / <span className="font-semibold text-[#375777]">{screen === "dashboard" ? "Dashboard" : screen === "for-you" ? "Para você" : screen === "explore" ? "Explorar" : screen === "matches" ? "Matches" : "Minha conta"}</span></div><div className="flex items-center gap-4"><button onClick={() => go("notifications")} className="relative rounded-lg p-2 text-[#687681] hover:bg-[#f2f5f7]"><Bell size={18} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-[#ffd43b]" /></button><div className="h-7 w-px bg-[#e7ebee]" /><button onClick={() => go("account")} className="flex items-center gap-2"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-[#d9e8f4] text-xs font-bold text-[#075394]">NH</div><span className="hidden text-xs font-semibold text-[#526371] md:block">Nexa Health</span><ChevronDown size={14} className="text-[#9ba4ac]" /></button></div></header><main className="mx-auto max-w-[1280px] px-5 py-8 md:px-9 md:py-10">{children}</main></div></div>; }

function PageTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description: string; action?: React.ReactNode }) { return <div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div>{eyebrow && <p className="mb-2 text-[10px] font-extrabold uppercase tracking-[.15em] text-[#8d98a2]">{eyebrow}</p>}<h1 className="text-[29px] font-extrabold tracking-[-.06em] text-[#062f61] md:text-[34px]">{title}</h1><p className="mt-2 text-sm text-[#707c87]">{description}</p></div>{action}</div>; }

function Dashboard({ go }: { go: (s: Screen) => void }) { return <><PageTitle title="Olá, Nexa Health 👋" description="Visão geral da sua atividade e das oportunidades que exigem atenção." action={<PrimaryButton secondary onClick={() => go("notifications")}>Ver atividade</PrimaryButton>} /><div className="mt-8 rounded-2xl bg-[#075394] p-6 text-white md:p-7"><div className="flex items-center justify-between gap-4"><div><p className="text-xs font-semibold text-[#c4d8eb]">Você tem 4 ações para acompanhar</p><h2 className="mt-2 text-[20px] font-extrabold tracking-[-.03em]">2 novos matches · 1 prazo próximo · 1 oportunidade atualizada</h2></div><Zap className="hidden text-[#ffd43b] md:block" size={30} fill="currentColor" /></div></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[["12", "Oportunidades salvas"], ["4", "Matches novos"], ["2", "Prazos esta semana"], ["7", "Em acompanhamento"]].map(([n, l]) => <div key={l} className="rounded-xl border border-[#e5eaee] bg-white p-5"><div className="text-[27px] font-extrabold tracking-[-.05em] text-[#062f61]">{n}</div><div className="mt-1 text-xs text-[#7d8993]">{l}</div></div>)}</div><div className="mt-8 grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-[#e5eaee] bg-white p-6"><div className="flex items-center justify-between"><h2 className="text-base font-extrabold text-[#062f61]">Próximos prazos</h2><button onClick={() => go("for-you")} className="text-xs font-bold text-[#075394]">Ver todos</button></div><div className="mt-5 space-y-3">{[["EDITAL", "Inovação Aberta 2026", "Inscrições encerram em 5 dias"], ["POC", "Gestão Inteligente", "Resposta necessária até sexta-feira"]].map(([type, title, sub]) => <div key={title} className="flex items-center gap-4 rounded-xl bg-[#f7f9fb] p-4"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#fff2b8] text-[9px] font-extrabold text-[#775b00]">{type}</div><div className="flex-1"><p className="text-xs font-bold text-[#294866]">{title}</p><p className="mt-1 text-[11px] text-[#89949d]">{sub}</p></div><ChevronRight size={16} className="text-[#9aa6af]" /></div>)}</div></section><section className="rounded-2xl bg-[#eaf2f8] p-6"><div className="flex items-center gap-2 text-[#075394]"><TrendingUp size={17} /><h2 className="text-base font-extrabold">Atividade recente</h2></div><div className="mt-5 space-y-5">{["Novo match: Nexa Health × Empresa Alpha", "Edital Inova+ teve atualização de prazo", "Seu perfil foi atualizado"].map((x, i) => <div key={x} className="flex gap-3 border-b border-[#d6e4ee] pb-4 last:border-0"><div className="mt-1 h-2 w-2 shrink-0 rounded-full bg-[#ffd43b]" /><div><p className="text-xs font-semibold text-[#2a4b6a]">{x}</p><p className="mt-1 text-[10px] text-[#8193a1]">{i === 0 ? "há 2 horas" : i === 1 ? "ontem" : "18 set, 14:10"}</p></div></div>)}</div></section></div></>; }

function OpportunityCard({ item, go }: { item: typeof opportunities[number]; go: (s: Screen) => void }) { return <article className="flex min-h-[210px] flex-col rounded-2xl border border-[#e1e6ea] bg-white p-5 transition hover:-translate-y-0.5 hover:shadow-[0_12px_28px_rgba(6,47,97,.08)]"><div className="flex items-start justify-between"><span className={`rounded-full px-3 py-1 text-[10px] font-extrabold ${item.color}`}>{item.type}</span><div className="text-right"><div className="text-[24px] font-extrabold tracking-[-.06em] text-[#25805e]">{item.match}%</div><div className="text-[10px] text-[#94a0a8]">match</div></div></div><h3 className="mt-4 text-[15px] font-extrabold leading-5 text-[#123b62]">{item.title}</h3><p className="mt-2 text-xs leading-5 text-[#75818b]">{item.short}</p><div className="mt-auto flex items-center justify-between gap-2 border-t border-[#eef1f3] pt-4"><span className="text-[10px] text-[#89959e]">Combina por: {item.tags}</span><button onClick={() => go("opportunity")} className="flex shrink-0 items-center gap-1 text-xs font-extrabold text-[#075394]">Ver oportunidade <ArrowRight size={13} /></button></div></article>; }

function Opportunities({ go, explore = false }: { go: (s: Screen) => void; explore?: boolean }) { const [query, setQuery] = useState(""); const [type, setType] = useState<OpportunityType>("Todos"); const list = useMemo(() => opportunities.filter((x) => (type === "Todos" || (type === "POCs" ? x.type === "POC" : x.type === type.slice(0, -1))) && `${x.title} ${x.short}`.toLowerCase().includes(query.toLowerCase())), [query, type]); return <><PageTitle title={explore ? "Explorar" : "Para você"} description={explore ? "Explore editais, eventos e clientes disponíveis na StartIn." : "O que a IA da StartIn encontrou para sua startup."} /><div className="mt-8 flex flex-col gap-3 rounded-xl border border-[#e0e5e9] bg-white p-3 md:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#96a1aa]" size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar editais, eventos ou clientes..." className="h-10 w-full bg-transparent pl-10 pr-3 text-sm outline-none placeholder:text-[#9ca7af]" /></div><button className="flex h-10 items-center justify-center gap-2 rounded-lg border border-[#dfe5e9] px-4 text-xs font-bold text-[#42617e]"><Filter size={14} /> Filtros</button><button className="flex h-10 items-center justify-center gap-2 rounded-lg border border-[#dfe5e9] px-4 text-xs font-bold text-[#42617e]">Ordenar <ChevronDown size={14} /></button></div><div className="mt-5 flex gap-2 overflow-auto pb-1">{(["Todos", "Editais", "Eventos", "POCs", "Compras"] as OpportunityType[]).map((x) => <button key={x} onClick={() => setType(x)} className={`rounded-full px-5 py-2 text-xs font-bold whitespace-nowrap ${type === x ? "bg-[#075394] text-white" : "bg-white text-[#45617e] ring-1 ring-[#e3e8ec]"}`}>{x}</button>)}</div><div className="mt-7 flex items-end justify-between"><div><h2 className="text-base font-extrabold text-[#123b62]">{list.length ? `${list.length === 4 ? 12 : list.length} oportunidades priorizadas` : "Nenhuma oportunidade encontrada"}</h2><p className="mt-1 text-xs text-[#88949d]">Ordenadas pela aderência ao perfil, objetivos e requisitos.</p></div>{!list.length && <button onClick={() => { setQuery(""); setType("Todos"); }} className="text-xs font-bold text-[#075394]">Limpar filtros</button>}</div>{list.length ? <div className="mt-5 grid gap-4 md:grid-cols-2">{list.map((item) => <OpportunityCard key={item.id} item={item} go={go} />)}</div> : <div className="mt-6 rounded-2xl border border-dashed border-[#d9e0e5] bg-white py-16 text-center"><Sparkles className="mx-auto text-[#ffd43b]" size={30} fill="currentColor" /><p className="mt-4 text-sm font-bold text-[#234666]">Não encontramos oportunidades compatíveis</p><p className="mx-auto mt-2 max-w-sm text-xs leading-5 text-[#8a969f]">Tente ampliar sua busca ou atualizar as preferências da startup.</p><button onClick={() => go("preferences")} className="mt-5 text-xs font-bold text-[#075394]">Atualizar preferências</button></div>}</>; }

function OpportunityDetail({ go }: { go: (s: Screen) => void }) { const [joined, setJoined] = useState(false); const item = opportunities[0]; return <><button onClick={() => go("for-you")} className="mb-7 flex items-center gap-2 text-xs font-bold text-[#6d7b87]"><ArrowLeft size={14} /> Voltar para Para você</button><div className="flex flex-col justify-between gap-5 md:flex-row md:items-start"><div><span className={`rounded-full px-3 py-1 text-[10px] font-extrabold ${item.color}`}>EDITAL</span><h1 className="mt-4 text-[29px] font-extrabold tracking-[-.05em] text-[#062f61]">{item.title}</h1><p className="mt-2 text-sm text-[#73808b]">{item.short}</p></div><div className="rounded-xl bg-[#e7f4ed] px-5 py-3 text-center"><div className="text-[25px] font-extrabold text-[#25805e]">{item.match}%</div><div className="text-[10px] text-[#477660]">de aderência</div></div></div><div className="mt-7 grid grid-cols-2 gap-3 md:grid-cols-4">{[["Prazo", "15/10/2026"], ["Localização", "Brasil · Remoto"], ["Modalidade", "Apoio financeiro"], ["Status", "Inscrições abertas"]].map(([a, b]) => <div key={a} className="rounded-xl border border-[#e2e7eb] bg-white p-4"><p className="text-[10px] font-semibold uppercase text-[#9aa4ac]">{a}</p><p className="mt-2 text-xs font-bold text-[#244766]">{b}</p></div>)}</div><div className="mt-8 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="rounded-2xl border border-[#e2e7eb] bg-white p-6"><h2 className="text-lg font-extrabold text-[#123b62]">Sobre a oportunidade</h2><p className="mt-4 text-sm leading-7 text-[#65747f]">{item.description}</p><h3 className="mt-8 text-sm font-extrabold text-[#123b62]">Por que este match faz sentido</h3><div className="mt-4 grid gap-3 md:grid-cols-3">{[["01", "Perfil", "Healthtech · SaaS · B2B"], ["02", "Tecnologias", "IA · Dados · Automação"], ["03", "Objetivo", "Validação em ambiente real"]].map(([n, t, d]) => <div key={n} className="rounded-xl bg-[#f5f8fa] p-4"><div className="text-[10px] font-extrabold text-[#075394]">{n}</div><p className="mt-3 text-xs font-bold text-[#345572]">{t}</p><p className="mt-1 text-[11px] leading-4 text-[#81909b]">{d}</p></div>)}</div></section><aside className="h-fit rounded-2xl bg-[#eaf2f8] p-6"><Sparkles className="text-[#075394]" size={20} /><h2 className="mt-4 text-lg font-extrabold leading-6 text-[#123b62]">Essa oportunidade combina com você</h2><p className="mt-3 text-xs leading-5 text-[#6d7e8b]">A IA identificou alta aderência entre seu perfil, suas tecnologias e os requisitos.</p><PrimaryButton full onClick={() => setJoined(true)}>{joined ? <><Check size={16} /> Interesse registrado</> : <>Participar <ArrowRight size={16} /></>}</PrimaryButton><button onClick={() => go("for-you")} className="mt-3 w-full text-center text-xs font-bold text-[#075394]">Voltar para oportunidades</button></aside></div></>; }

function Matches({ go }: { go: (s: Screen) => void }) { return <><PageTitle title="Seus matches" description="Conexões com maior potencial para sua startup." /><div className="mt-8 rounded-2xl bg-[#075394] p-6 text-white"><div className="text-[30px] font-extrabold tracking-[-.06em]">92%</div><p className="mt-1 text-xs text-[#c8dded]">de compatibilidade média</p></div><div className="mt-5 grid gap-4 md:grid-cols-2">{[["POC", "Nexa × Empresa Alpha", "POC em IA para gestão operacional.", "94%"], ["Edital", "Nexa × Edital Inova+", "Oportunidade de financiamento e validação.", "91%"]].map(([type, title, desc, pct]) => <div key={title} className="rounded-2xl border border-[#e1e6ea] bg-white p-5"><div className="flex items-start justify-between"><span className="rounded-full bg-[#fff2b8] px-3 py-1 text-[10px] font-extrabold text-[#795900]">{type}</span><span className="text-xl font-extrabold text-[#25805e]">{pct}</span></div><h3 className="mt-6 text-sm font-extrabold text-[#123b62]">{title}</h3><p className="mt-2 text-xs text-[#74818c]">{desc}</p><button onClick={() => go("match")} className="mt-6 flex items-center gap-2 text-xs font-extrabold text-[#075394]">Ver oportunidade <ArrowRight size={14} /></button></div>)}</div><section className="mt-8 rounded-2xl border border-[#e1e6ea] bg-white p-6"><h2 className="text-base font-extrabold text-[#123b62]">Status das conexões</h2><div className="mt-5 grid gap-3 md:grid-cols-3">{[["01", "Interesse enviado", "3 conexões"], ["02", "Contato iniciado", "1 conexão"], ["03", "Em negociação", "1 conexão"]].map(([n, t, d]) => <div key={n} className="rounded-xl bg-[#f6f8fa] p-4"><span className="text-[10px] font-extrabold text-[#075394]">{n}</span><p className="mt-3 text-xs font-bold text-[#31516e]">{t}</p><p className="mt-1 text-[11px] text-[#8a969f]">{d}</p></div>)}</div></section></>; }

function MatchDetail({ go }: { go: (s: Screen) => void }) { const [saved, setSaved] = useState(false); return <><button onClick={() => go("matches")} className="mb-7 flex items-center gap-2 text-xs font-bold text-[#6d7b87]"><ArrowLeft size={14} /> Voltar para matches</button><PageTitle title="Detalhe do match" description="Entenda de forma transparente por que esta conexão foi recomendada." /><div className="mt-8 flex flex-col justify-between gap-5 rounded-2xl bg-[#075394] p-6 text-white md:flex-row md:items-center"><div><p className="text-xs font-bold text-[#c8dded]">Nexa Health × Empresa Alpha</p><h2 className="mt-2 text-xl font-extrabold">POC · Inteligência operacional</h2></div><div className="text-left md:text-right"><div className="text-4xl font-extrabold tracking-[-.08em] text-[#ffd43b]">94%</div><div className="text-xs text-[#c8dded]">aderência</div></div></div><section className="mt-6 rounded-2xl border border-[#e1e6ea] bg-white p-6"><h2 className="text-lg font-extrabold text-[#123b62]">Por que este match faz sentido</h2><div className="mt-6 space-y-5">{[["01", "Perfil da startup", "Healthtech · SaaS · B2B", "A startup atua no mesmo contexto da demanda."], ["02", "Requisitos", "IA · Dados · Automação", "As tecnologias declaradas atendem aos requisitos."], ["03", "Objetivo", "POC para gestão operacional", "O objetivo da oportunidade é compatível com sua solução."], ["04", "Contexto", "Brasil · B2B · validação", "Localização e modelo de negócio são compatíveis."]].map(([n, t, v, d]) => <div key={n} className="flex gap-4 border-b border-[#eef1f3] pb-5 last:border-0 last:pb-0"><span className="text-xs font-extrabold text-[#075394]">{n}</span><div className="min-w-0 flex-1"><p className="text-sm font-extrabold text-[#294c6a]">{t}</p><p className="mt-1 text-xs font-semibold text-[#688093]">{v}</p></div><p className="hidden max-w-[320px] text-xs leading-5 text-[#7c8a94] md:block">{d}</p></div>)}</div><div className="mt-8 flex flex-wrap gap-3"><PrimaryButton onClick={() => go("opportunity")}>Ver oportunidade <ArrowRight size={16} /></PrimaryButton><PrimaryButton secondary onClick={() => setSaved(!saved)}>{saved ? <><Check size={16} /> Match salvo</> : <><Heart size={16} /> Salvar match</>}</PrimaryButton></div></section></>; }

function Assistant() { const [messages, setMessages] = useState<{from: "ai" | "me"; text: string}[]>([{ from: "ai", text: "Busquei na web e encontrei 8 oportunidades relevantes para o seu perfil. A IA analisou editais, eventos e oportunidades de clientes e priorizou os resultados pelo nível de aderência." }]); const [input, setInput] = useState(""); const send = (text = input) => { if (!text.trim()) return; setMessages((m) => [...m, { from: "me", text }, { from: "ai", text: "Encontrei uma nova seleção com base no seu perfil. Posso abrir os resultados priorizados para você." }]); setInput(""); }; return <><PageTitle title="Assistente IA" description="Sua IA para buscar oportunidades na web, analisar dados e apoiar decisões." /><div className="mt-8 grid gap-5 lg:grid-cols-[.75fr_1.25fr]"><aside className="rounded-2xl bg-[#075394] p-6 text-white"><Bot size={25} className="text-[#ffd43b]" /><h2 className="mt-6 text-[25px] font-extrabold leading-7 tracking-[-.05em]">Como posso ajudar?</h2><p className="mt-3 text-sm leading-5 text-[#c7dceb]">Posso ajudar você a encontrar oportunidades mais relevantes.</p><div className="mt-8 space-y-2">{["Buscar editais na web", "Buscar eventos na web", "Priorizar meus matches", "Analisar oportunidade"].map((x) => <button key={x} onClick={() => send(x)} className="flex w-full items-center justify-between rounded-lg border border-white/20 px-3 py-3 text-left text-xs font-semibold text-white hover:bg-white/10">{x}<ArrowRight size={14} /></button>)}</div></aside><section className="flex min-h-[480px] flex-col rounded-2xl border border-[#e1e6ea] bg-white"><div className="border-b border-[#edf0f2] p-5"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#eaf2f8] text-[#075394]"><Bot size={18} /></div><div><p className="text-sm font-extrabold text-[#123b62]">STARTIN IA</p><p className="text-[10px] text-[#8b969f]">Online agora</p></div></div></div><div className="flex-1 space-y-4 overflow-auto p-5">{messages.map((m, i) => <div key={i} className={`flex ${m.from === "me" ? "justify-end" : "justify-start"}`}><div className={`max-w-[80%] rounded-2xl px-4 py-3 text-xs leading-5 ${m.from === "me" ? "rounded-br-sm bg-[#075394] text-white" : "rounded-bl-sm bg-[#f0f5f8] text-[#42617e]"}`}>{m.text}</div></div>)}</div><div className="m-4 flex items-center gap-2 rounded-xl bg-[#f5f7f9] p-2"><input value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === "Enter" && send()} placeholder="Pergunte sobre editais, eventos, clientes ou matches..." className="h-9 flex-1 bg-transparent px-2 text-xs outline-none placeholder:text-[#99a4ad]" /><button onClick={() => send()} className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#075394] text-white"><Send size={15} /></button></div></section></div></>; }

function Startup({ go }: { go: (s: Screen) => void }) { const [saved, setSaved] = useState(false); return <><PageTitle title="Minha startup" description="Perfil usado para personalizar os matches e as buscas da IA." action={<PrimaryButton secondary>Editar perfil</PrimaryButton>} /><section className="mt-8 flex items-center gap-5 rounded-2xl border border-[#e2e7eb] bg-white p-6"><div className="flex h-16 w-16 items-center justify-center rounded-full bg-[#062f61] text-lg font-extrabold text-white">NH</div><div><h2 className="text-xl font-extrabold text-[#123b62]">Nexa Health</h2><p className="mt-1 text-sm text-[#76838d]">Healthtech · SaaS · B2B</p></div></section><section className="mt-7 rounded-2xl border border-[#e2e7eb] bg-white p-6"><h2 className="text-lg font-extrabold text-[#123b62]">Preferências de matching</h2><div className="mt-7 grid gap-7 md:grid-cols-2"><div><p className="text-xs font-bold text-[#50697f]">Áreas de interesse</p><div className="mt-3 flex flex-wrap gap-2">{["IA", "Saúde", "Dados", "Automação"].map((x) => <span key={x} className="rounded-full bg-[#eaf2f8] px-4 py-2 text-xs font-bold text-[#075394]">{x}</span>)}</div></div><div><p className="text-xs font-bold text-[#50697f]">Tipos de oportunidade de interesse</p><div className="mt-3 flex flex-wrap gap-2">{["POC", "Compra", "Editais"].map((x) => <span key={x} className={`rounded-full px-4 py-2 text-xs font-bold ${x === "POC" ? "bg-[#075394] text-white" : "bg-[#f3f5f6] text-[#557086]"}`}>{x}</span>)}</div></div></div><div className="mt-8 flex items-center justify-between border-t border-[#edf0f2] pt-6"><div><p className="text-sm font-bold text-[#284a67]">Receber recomendações da IA</p><p className="mt-1 text-xs text-[#82909a]">Use seu perfil para personalizar novas oportunidades.</p></div><button onClick={() => setSaved(!saved)} className={`flex h-7 w-12 items-center rounded-full p-1 ${saved ? "bg-[#075394]" : "bg-[#b8c4cc]"}`}><span className={`h-5 w-5 rounded-full bg-white transition ${saved ? "translate-x-5" : ""}`} /></button></div><div className="mt-7 flex justify-end"><PrimaryButton onClick={() => go("dashboard")}>Salvar preferências <Check size={15} /></PrimaryButton></div></section></>; }

function MyOpportunities({ go }: { go: (s: Screen) => void }) { return <><PageTitle title="Minhas oportunidades" description="Acompanhe, edite e gerencie as oportunidades publicadas pela sua organização." action={<PrimaryButton onClick={() => go("create-opportunity")}><Plus size={15} /> Nova oportunidade</PrimaryButton>} /><section className="mt-8 rounded-2xl border border-[#e2e7eb] bg-white p-6"><h2 className="text-sm font-extrabold text-[#123b62]">Resumo das oportunidades</h2><div className="mt-4 grid gap-3 md:grid-cols-3">{[["3", "publicadas"], ["1", "em análise"], ["2", "encerradas"]].map(([n, t], i) => <div key={t} className={`rounded-xl p-5 ${i === 0 ? "bg-[#075394] text-white" : "bg-[#f3f6f8] text-[#294b68]"}`}><div className="text-2xl font-extrabold">{n}</div><div className="mt-1 text-xs font-semibold opacity-80">{t}</div></div>)}</div><h2 className="mt-8 text-sm font-extrabold text-[#123b62]">Oportunidades recentes</h2><div className="mt-4 rounded-xl bg-[#f7f9fa] p-5"><div className="flex items-start justify-between"><div><p className="text-sm font-extrabold text-[#2b4b66]">POC — Inteligência Operacional</p><p className="mt-2 text-xs text-[#788791]">Empresa busca startup para automatizar processos internos.</p></div><button><MoreHorizontal size={17} className="text-[#82909a]" /></button></div><div className="mt-5 flex flex-wrap gap-2">{["IA", "SaaS", "B2B", "Dados"].map((x) => <span key={x} className="rounded-full bg-white px-3 py-1 text-[10px] font-bold text-[#52708a]">{x}</span>)}</div></div></section></>; }

function CreateForm({ go, opportunity = false }: { go: (s: Screen) => void; opportunity?: boolean }) { const [published, setPublished] = useState(false); if (published) return <div className="mx-auto max-w-[680px] py-14 text-center"><div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-[#d9f1e5] text-[#18734d]"><Check size={30} strokeWidth={3} /></div><h1 className="mt-7 text-[30px] font-extrabold tracking-[-.05em] text-[#062f61]">{opportunity ? "Oportunidade cadastrada!" : "Empresa cadastrada!"}</h1><p className="mt-3 text-sm text-[#73818c]">{opportunity ? "Sua oportunidade foi salva com sucesso e já pode entrar no matching da StartIn." : "Sua organização foi salva e já pode publicar novas oportunidades."}</p><div className="mt-8 flex justify-center gap-3"><PrimaryButton secondary onClick={() => go("my-opportunities")}>Minhas oportunidades</PrimaryButton><PrimaryButton onClick={() => go("dashboard")}>Ir para dashboard</PrimaryButton></div></div>; return <><PageTitle title={opportunity ? "Cadastrar oportunidade" : "Cadastrar empresa"} description={opportunity ? "Empresas e organizações publicam oportunidades para encontrar startups aderentes." : "Cadastre sua empresa ou organização para publicar oportunidades."} /><section className="mt-8 rounded-2xl border border-[#e2e7eb] bg-white p-6 md:p-8"><div className="flex gap-2 overflow-auto">{(opportunity ? ["POC", "Compra", "POC + Compra"] : ["Empresa", "Organização", "Instituição"]).map((x, i) => <button key={x} className={`rounded-lg px-6 py-3 text-xs font-bold whitespace-nowrap ${i === 0 ? "bg-[#075394] text-white" : "bg-[#f3f6f8] text-[#486680]"}`}>{x}</button>)}</div><div className="mt-8 grid gap-5 md:grid-cols-2"><div className="md:col-span-2"><Field label={opportunity ? "Título" : "Nome da empresa ou organização"} placeholder={opportunity ? "Desafio de inteligência operacional" : "Empresa Alpha"} /></div><div className="md:col-span-2"><label className="block"><span className="mb-2 block text-xs font-semibold text-[#203754]">{opportunity ? "Descrição da oportunidade" : "Descreva sua organização, área de atuação e principais demandas de inovação."}</span><textarea className="min-h-[130px] w-full rounded-lg border border-[#dfe4e9] p-3 text-sm outline-none focus:border-[#075394]" placeholder="Descreva o problema, objetivo, público-alvo e critérios para a solução." /></label></div><div className="md:col-span-2"><p className="mb-3 text-xs font-semibold text-[#203754]">{opportunity ? "Perfil de startup desejado para o match" : "Área de atuação · porte · localização"}</p><div className="flex flex-wrap gap-2">{["IA", "SaaS", "B2B", "Dados"].map((x) => <button key={x} className="rounded-full bg-[#edf3f7] px-4 py-2 text-xs font-bold text-[#075394]">{x}</button>)}</div></div></div><div className="mt-8 flex justify-end"><PrimaryButton onClick={() => { setPublished(true); }}>{opportunity ? "Publicar oportunidade" : "Continuar cadastro"} <ArrowRight size={16} /></PrimaryButton></div></section></>; }

function SettingsPage({ go }: { go: (s: Screen) => void }) { const cards: [Screen, React.ElementType, string, string][] = [["account", UserRound, "Conta e acesso", "E-mail, senha e informações básicas da sua conta."], ["preferences", Target, "Preferências de matching", "Ajuste os critérios usados pela IA para encontrar oportunidades."], ["privacy", Shield, "Privacidade e segurança", "Controle seus dados, visibilidade do perfil e sessões ativas."], ["notifications", Bell, "Notificações", "Escolha quais alertas você deseja receber e por onde."]]; return <><PageTitle title="Configurações" description="Gerencie sua conta, preferências e privacidade na StartIn." /><div className="mt-8 grid gap-4 md:grid-cols-2">{cards.map(([screen, Icon, title, text]) => <button key={title} onClick={() => go(screen)} className="group rounded-2xl border border-[#e2e7eb] bg-white p-6 text-left hover:border-[#b8cad8]"><Icon className="text-[#075394]" size={20} /><div className="mt-5 flex items-center justify-between"><div><h2 className="text-base font-extrabold text-[#123b62]">{title}</h2><p className="mt-2 max-w-[310px] text-xs leading-5 text-[#788691]">{text}</p></div><ArrowRight className="text-[#7f8f9a] transition group-hover:translate-x-1" size={18} /></div></button>)}</div><section className="mt-5 rounded-2xl border border-[#e2e7eb] bg-white p-6"><h2 className="text-base font-extrabold text-[#123b62]">Preferências rápidas</h2>{["Mostrar recomendações personalizadas", "Receber novidades e oportunidades por e-mail", "Alertas de novos matches"].map((x, i) => <div key={x} className="flex items-center justify-between border-b border-[#eef1f3] py-5 last:border-0"><span className="text-sm text-[#42617e]">{x}</span><div className="h-6 w-10 rounded-full bg-[#075394] p-1"><div className={`h-4 w-4 rounded-full bg-white ${i === 1 ? "translate-x-4" : ""}`} /></div></div>)}</section></>; }

function SubSettings({ screen, go }: { screen: Screen; go: (s: Screen) => void }) { const titles: Record<string, [string, string]> = { account: ["Conta e acesso", "Gerencie seus dados de acesso e informações básicas da sua conta."], privacy: ["Privacidade e segurança", "Controle a visibilidade do seu perfil, seus dados e as sessões ativas."], preferences: ["Preferências de matching", "Defina o que é mais relevante para a IA encontrar oportunidades para sua startup."], notifications: ["Notificações", "Acompanhe matches, oportunidades e atualizações importantes."] }; const [title, description] = titles[screen]; if (screen === "notifications") return <><PageTitle title={title} description={description} /><div className="mt-7 flex gap-2">{["Todas", "Oportunidades", "Matches", "Sistema"].map((x, i) => <button key={x} className={`rounded-full px-4 py-2 text-xs font-bold ${i === 0 ? "bg-[#075394] text-white" : "bg-white text-[#46627c] ring-1 ring-[#e3e8ec]"}`}>{x}</button>)}</div><div className="mt-5 space-y-3">{[["Novo match encontrado", "Uma oportunidade de POC teve 94% de compatibilidade com sua startup.", "Hoje, 09:42"], ["Novo edital recomendado", "A StartIn encontrou um edital alinhado ao seu perfil de atuação.", "Hoje, 08:15"], ["Evento próximo do seu perfil", "Tech & Innovation Week pode gerar conexões relevantes para sua startup.", "Ontem, 17:30"], ["Seu perfil foi atualizado", "As preferências de matching foram aplicadas às novas recomendações.", "18 set, 14:10"]].map(([a, b, c]) => <div key={a} className="flex gap-4 rounded-2xl border border-[#e2e7eb] bg-white p-5"><div className="mt-1 h-9 w-9 shrink-0 rounded-full bg-[#eaf2f8]" /><div><p className="text-sm font-extrabold text-[#244766]">{a}</p><p className="mt-1 text-xs text-[#70808c]">{b}</p><p className="mt-3 text-[10px] text-[#9aa5ad]">{c}</p></div></div>)}</div></>; return <><button onClick={() => go("settings")} className="mb-7 flex items-center gap-2 text-xs font-bold text-[#6d7b87]"><ArrowLeft size={14} /> Voltar para configurações</button><PageTitle title={title} description={description} /><section className="mt-8 rounded-2xl border border-[#e2e7eb] bg-white p-6 md:p-8">{screen === "account" && <><h2 className="text-base font-extrabold text-[#123b62]">Informações da conta</h2><div className="mt-6 grid gap-5 md:grid-cols-2"><Field label="Nome completo" value="Eduarda" /><Field label="E-mail" value="eduarda@exemplo.com" /></div><button className="mt-5 text-xs font-bold text-[#075394]">Editar informações</button><div className="mt-8 border-t border-[#edf0f2] pt-7"><h2 className="text-base font-extrabold text-[#123b62]">Excluir conta</h2><p className="mt-3 text-xs text-[#768692]">Essa ação remove permanentemente os dados locais desta conta.</p><button className="mt-4 rounded-lg bg-[#d71920] px-5 py-3 text-xs font-bold text-white">Excluir</button></div><div className="mt-8 border-t border-[#edf0f2] pt-7"><h2 className="text-base font-extrabold text-[#123b62]">Segurança</h2><p className="mt-4 text-xs text-[#768692]">Senha · ••••••••••••</p><PrimaryButton secondary>Alterar senha</PrimaryButton></div></>}{screen === "privacy" && <><h2 className="text-base font-extrabold text-[#123b62]">Visibilidade e dados</h2>{["Perfil público", "Dados e recomendações"].map((x, i) => <div key={x} className="flex items-center justify-between border-b border-[#edf0f2] py-6"><div><p className="text-sm font-bold text-[#284a67]">{x}</p><p className="mt-1 text-xs text-[#82909a]">{i ? "Usar dados do perfil para personalizar recomendações." : "Permitir que outras pessoas encontrem sua startup na StartIn."}</p></div><div className={`h-6 w-10 rounded-full p-1 ${i ? "bg-[#d9e0e5]" : "bg-[#075394]"}`}><div className={`h-4 w-4 rounded-full bg-white ${i ? "" : "translate-x-4"}`} /></div></div>)}<h2 className="mt-8 text-base font-extrabold text-[#123b62]">Segurança da conta</h2><p className="mt-4 text-xs text-[#768692]">Windows · Chrome · Sessão atual</p><button className="mt-4 text-xs font-bold text-[#075394]">Encerrar outras sessões</button></>}{screen === "preferences" && <><h2 className="text-base font-extrabold text-[#123b62]">Tipo de oportunidade</h2><div className="mt-4 flex flex-wrap gap-2">{["POC", "Compra", "POC + compra"].map((x, i) => <button key={x} className={`rounded-lg px-5 py-3 text-xs font-bold ${i === 0 ? "bg-[#075394] text-white" : "bg-[#f3f6f8] text-[#486680]"}`}>{x}</button>)}</div><h2 className="mt-9 text-base font-extrabold text-[#123b62]">Critérios de interesse</h2><div className="mt-5 grid gap-4 md:grid-cols-3">{["Setor e segmento", "Tecnologia e solução", "Localização", "Estágio da startup", "Faixa de investimento"].map((x) => <label key={x} className="text-xs font-semibold text-[#587086]">{x}<select className="mt-2 h-10 w-full rounded-lg border-0 bg-[#f3f6f8] px-3 text-xs text-[#71818d]"><option>Selecionar</option><option>Brasil</option><option>Healthtech</option></select></label>)}</div><p className="mt-5 text-xs text-[#84919a]">A IA usará essas preferências para personalizar seus matches.</p></>}</section></>; }

function Reset({ go }: { go: (s: Screen) => void }) { return <AuthShell sideTitle={<>Recupere o acesso à sua <span className="text-[#ffd43b]">conta.</span></>} sideText="Defina uma nova senha segura para continuar usando a StartIn."><h2 className="text-[28px] font-extrabold tracking-[-.05em] text-[#062f61]">Crie uma nova senha</h2><p className="mt-2 text-sm text-[#77818c]">Escolha uma senha forte para proteger sua conta.</p><div className="mt-7 space-y-4"><Field label="Nova senha" placeholder="Digite sua nova senha" type="password" /><Field label="Confirmar nova senha" placeholder="Repita sua nova senha" type="password" /><p className="text-[11px] text-[#7e8b95]">A senha deve ter pelo menos 8 caracteres.</p><PrimaryButton full onClick={() => go("login")}>Redefinir senha <Check size={16} /></PrimaryButton></div></AuthShell>; }

function Verify({ go }: { go: (s: Screen) => void }) { return <AuthShell sideTitle={<>Confirme seu e-mail para <span className="text-[#ffd43b]">continuar.</span></>} sideText="Enviamos um link de confirmação para validar sua conta antes de configurar sua startup."><div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-[#eaf2f8] text-[#075394]"><Mail size={24} /></div><h2 className="mt-7 text-[28px] font-extrabold tracking-[-.05em] text-[#062f61]">Verifique seu e-mail</h2><p className="mt-3 text-sm leading-5 text-[#77818c]">Enviamos uma mensagem para <strong>seu@email.com</strong>.</p><PrimaryButton full onClick={() => go("onboarding")} >Abrir e-mail <ArrowRight size={16} /></PrimaryButton><button className="mt-5 w-full text-center text-xs font-bold text-[#075394]">Não recebeu? Reenviar e-mail</button></AuthShell>; }

export default function Home() { const [screen, setScreen] = useState<Screen>(() => localStorage.getItem("startin-auth") ? "dashboard" : "login"); const [selectedScreen, setSelectedScreen] = useState<Screen>(screen); useEffect(() => setSelectedScreen(screen), [screen]); const go = (next: Screen) => { setScreen(next); setSelectedScreen(next); window.scrollTo({ top: 0, behavior: "smooth" }); }; if (["login", "signup", "recovery", "reset", "verify", "onboarding"].includes(screen)) { if (screen === "login") return <Login go={go} />; if (screen === "signup") return <Signup go={go} />; if (screen === "recovery") return <Recovery go={go} />; if (screen === "reset") return <Reset go={go} />; if (screen === "verify") return <Verify go={go} />; return <Onboarding go={go} />; } let page: React.ReactNode = null; if (screen === "dashboard") page = <Dashboard go={go} />; else if (screen === "for-you") page = <Opportunities go={go} />; else if (screen === "explore") page = <Opportunities go={go} explore />; else if (screen === "opportunity") page = <OpportunityDetail go={go} />; else if (screen === "matches") page = <Matches go={go} />; else if (screen === "match") page = <MatchDetail go={go} />; else if (screen === "assistant") page = <Assistant />; else if (screen === "startup") page = <Startup go={go} />; else if (screen === "my-opportunities") page = <MyOpportunities go={go} />; else if (screen === "create-company") page = <CreateForm go={go} />; else if (screen === "create-opportunity") page = <CreateForm go={go} opportunity />; else if (screen === "settings") page = <SettingsPage go={go} />; else if (["account", "privacy", "preferences", "notifications"].includes(screen)) page = <SubSettings screen={screen} go={go} />; else page = <Dashboard go={go} />; return <AppShell screen={selectedScreen} go={go}>{page}</AppShell>; }
